def investigate(context, acquire):
    hist = acquire("history")
    # Determine put conflict behavior and channel from history.
    # Family: put is IGNORE, REPLACE, or UPSERT(value).
    # channel: main changes(), main total_changes, main+other total_changes.
    # trigger: absent or AFTER INSERT logging one row.
    # We infer by simulating each candidate and matching observed channel/count/sum.

    def simulate(actions, put_mode, channel_mode, trigger):
        # returns (channel, committed_count, committed_sum)
        # state: committed dict key->value
        committed = {}
        # pending per connection: dict key->value or None for delete
        pending = {"main": {}, "other": {}}
        in_tx = {"main": False, "other": False}
        # counters
        changes = {"main": 0, "other": 0}
        total = {"main": 0, "other": 0}
        # trigger log count (unread, but affects total_changes)
        # We'll track total_changes including trigger inserts.
        # For changes(), trigger does not affect changes() of the statement? Actually
        # changes() returns rows changed by most recent statement, including trigger? 
        # In SQLite, changes() does not count trigger changes. total_changes does.
        # We'll model: direct changes counted in changes; trigger adds to total.
        last_changes = {"main": 0, "other": 0}

        def apply_write(conn, key, value, is_delete):
            nonlocal committed
            # determine current visible value for this connection
            # if in transaction, use pending overlay; else committed
            if in_tx[conn]:
                cur = pending[conn].get(key, committed.get(key, None))
            else:
                cur = committed.get(key, None)
            direct = 0
            trig = 0
            if is_delete:
                if cur is not None:
                    direct = 1
                    if in_tx[conn]:
                        pending[conn][key] = None
                    else:
                        del committed[key]
            else:
                if put_mode == "ignore":
                    if cur is None:
                        direct = 1
                        if in_tx[conn]:
                            pending[conn][key] = value
                        else:
                            committed[key] = value
                elif put_mode == "replace":
                    direct = 1
                    if in_tx[conn]:
                        pending[conn][key] = value
                    else:
                        committed[key] = value
                else:  # upsert
                    if cur is None:
                        direct = 1
                        if in_tx[conn]:
                            pending[conn][key] = value
                        else:
                            committed[key] = value
                    else:
                        if cur != value:
                            direct = 1
                            if in_tx[conn]:
                                pending[conn][key] = value
                            else:
                                committed[key] = value
            if direct and trigger:
                trig = 1
            last_changes[conn] = direct
            total[conn] += direct + trig
            return direct, trig

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                in_tx[conn] = True
                pending[conn] = {}
            elif op == "commit":
                for k, v in pending[conn].items():
                    if v is None:
                        if k in committed:
                            del committed[k]
                    else:
                        committed[k] = v
                pending[conn] = {}
                in_tx[conn] = False
            elif op == "rollback":
                pending[conn] = {}
                in_tx[conn] = False
            elif op == "put":
                apply_write(conn, act["key"], act["value"], False)
            elif op == "update":
                # update changes existing item's value; if not exists, no change
                key = act["key"]
                value = act["value"]
                if in_tx[conn]:
                    cur = pending[conn].get(key, committed.get(key, None))
                else:
                    cur = committed.get(key, None)
                if cur is not None:
                    if in_tx[conn]:
                        pending[conn][key] = value
                    else:
                        committed[key] = value
                    last_changes[conn] = 1
                    total[conn] += 1
                    if trigger:
                        total[conn] += 1
                else:
                    last_changes[conn] = 0
            elif op == "delete":
                apply_write(conn, act["key"], None, True)

        if channel_mode == "changes":
            ch = last_changes["main"]
        elif channel_mode == "total_main":
            ch = total["main"]
        else:
            ch = total["main"] + total["other"]
        cnt = len(committed)
        sm = sum(committed.values())
        return ch, cnt, sm

    # Determine which candidates are consistent with all history receipts.
    candidates = []
    for put_mode in ["ignore", "replace", "upsert"]:
        for channel_mode in ["changes", "total_main", "total_both"]:
            for trigger in [False, True]:
                ok = True
                for rec in hist:
                    ch, cnt, sm = simulate(rec["actions"], put_mode, channel_mode, trigger)
                    obs = rec["observed"]
                    if ch != obs["channel"] or cnt != obs["committed_count"] or sm != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    candidates.append((put_mode, channel_mode, trigger))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    results = set()
    for put_mode, channel_mode, trigger in candidates:
        ch, cnt, sm = simulate(actions, put_mode, channel_mode, trigger)
        if goal == "channel":
            results.add(ch)
        elif goal == "committed_count":
            results.add(cnt)
        elif goal == "committed_sum":
            results.add(sm)
        else:
            return {"value": None, "unresolved": True}
    if len(results) == 1:
        return {"value": results.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}
